I.scoreboard=`<rect x="8" y="8" width="48" height="32" rx="3" fill="#fff" ${L}/><rect x="13" y="14" width="14" height="20" fill="#5AB8FF"/><rect x="37" y="14" width="14" height="20" fill="#FF8FB1"/><text x="20" y="30" text-anchor="middle" font-size="14" font-weight="800" fill="#fff" font-family="sans-serif">2</text><text x="44" y="30" text-anchor="middle" font-size="14" font-weight="800" fill="#fff" font-family="sans-serif">1</text><path d="M16 40 l-4 18 M48 40 l4 18" ${L}/>`;
