I.rattanhoop=`<circle cx="32" cy="32" r="22" ${N} stroke="#A1887F" stroke-width="7"/><circle cx="32" cy="32" r="22" ${N} stroke="#6D4C41" stroke-width="2" stroke-dasharray="3 5"/>`;
I.bunting=`<path d="M4 12 q28 16 56 0" ${N} stroke="#2A2F6B" stroke-width="2"/>`+[[10,16,'#FF6B6B'],[22,21,'#FFD23F'],[34,22,'#6FD6A8'],[46,19,'#5AB8FF'],[56,14,'#FF8FB1']].map(([x,y,f])=>`<path d="M${x-5} ${y-2} L${x+5} ${y} L${x} ${y+16} Z" fill="${f}" ${L}/>`).join('');
