const T=(x,y,t,sz,f)=>`<text x="${x}" y="${y}" text-anchor="middle" font-size="${sz}" font-weight="800" fill="${f||'#2A2F6B'}" font-family="sans-serif">${t}</text>`;
// a fish: body colour, fin colour, body height, extras
const fish=(body,fin,h,extra)=>`<path d="M48 32 l12 -10 v20z" fill="${fin}" ${L}/><path d="M6 32 q14 -${h} 42 0 q-28 ${h} -42 0z" fill="${body}" ${L}/><path d="M24 ${32-h*0.45} q8 -8 14 -${h*0.1}" ${N} stroke="${fin}" stroke-width="4"/><circle cx="14" cy="30" r="2.5" fill="#fff" stroke="#2A2F6B" stroke-width="1.5"/>${extra||''}`;
const I={};
I.piranha=fish('#90A4AE','#E53935',24,`<path d="M6 33 q4 4 8 2" ${N} stroke="#E53935" stroke-width="3"/>`+[[22,28],[28,34],[34,28],[30,24]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="1.3" fill="#546E7A"/>`).join(''));
