I.subway=`<path d="M4 26 h56" stroke="#2A2F6B" stroke-width="2"/><path d="M6 26 v8 h8 v8 h8 v8 h8 v8 h30 v-32" fill="#E0E0E0" ${L}/><path d="M34 58 v-16 q12 -10 24 0 v16" fill="#37474F" ${L}/><path d="M10 16 v10 M10 16 h22" ${N} stroke="#FFB300" stroke-width="3"/><path d="M40 12 l6 6 l6 -6" ${N} stroke="#43A047" stroke-width="3"/><path d="M46 6 v12" stroke="#43A047" stroke-width="3"/>`;
